-- MySQL 8.0.16+; nhập vào database đã tạo trong phpMyAdmin.
-- Cấu trúc và cấu hình ban đầu, không chứa tài khoản hoặc nội dung mẫu.
-- UUID được ứng dụng tạo khi thêm dữ liệu. Không phải bản sao lưu.

CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY,applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS roles (name VARCHAR(20) PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO roles(name) VALUES ('SUPER_ADMIN'),('ADMIN'),('EDITOR'),('AUTHOR') ON DUPLICATE KEY UPDATE name=name;

CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,active BOOLEAN NOT NULL DEFAULT true,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(role) REFERENCES roles(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sessions (token_hash VARCHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,expires_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX sessions_expiry(expires_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (id CHAR(36) PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT (''),content LONGTEXT NOT NULL DEFAULT (''),cover TEXT NOT NULL DEFAULT (''),status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'PUBLISHED',author_id CHAR(36),category_id CHAR(36),data JSON NOT NULL DEFAULT (JSON_OBJECT()),views INTEGER NOT NULL DEFAULT 0,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deleted_at DATETIME(3),INDEX(status,published_at),INDEX(author_id),FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS posts (id CHAR(36) PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT (''),content LONGTEXT NOT NULL DEFAULT (''),cover TEXT NOT NULL DEFAULT (''),status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'DRAFT',author_id CHAR(36),category_id CHAR(36),data JSON NOT NULL DEFAULT (JSON_OBJECT()),views INTEGER NOT NULL DEFAULT 0,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deleted_at DATETIME(3),INDEX(status,published_at),INDEX(author_id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS announcements (id CHAR(36) PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT (''),content LONGTEXT NOT NULL DEFAULT (''),cover TEXT NOT NULL DEFAULT (''),status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'DRAFT',author_id CHAR(36),category_id CHAR(36),data JSON NOT NULL DEFAULT (JSON_OBJECT()),views INTEGER NOT NULL DEFAULT 0,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deleted_at DATETIME(3),INDEX(status,published_at),INDEX(author_id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS events (id CHAR(36) PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT (''),content LONGTEXT NOT NULL DEFAULT (''),cover TEXT NOT NULL DEFAULT (''),status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'DRAFT',author_id CHAR(36),category_id CHAR(36),data JSON NOT NULL DEFAULT (JSON_OBJECT()),views INTEGER NOT NULL DEFAULT 0,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deleted_at DATETIME(3),INDEX(status,published_at),INDEX(author_id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS albums (id CHAR(36) PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT (''),content LONGTEXT NOT NULL DEFAULT (''),cover TEXT NOT NULL DEFAULT (''),status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'DRAFT',author_id CHAR(36),category_id CHAR(36),data JSON NOT NULL DEFAULT (JSON_OBJECT()),views INTEGER NOT NULL DEFAULT 0,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deleted_at DATETIME(3),INDEX(status,published_at),INDEX(author_id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS videos (id CHAR(36) PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT (''),content LONGTEXT NOT NULL DEFAULT (''),cover TEXT NOT NULL DEFAULT (''),status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'DRAFT',author_id CHAR(36),category_id CHAR(36),data JSON NOT NULL DEFAULT (JSON_OBJECT()),views INTEGER NOT NULL DEFAULT 0,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deleted_at DATETIME(3),INDEX(status,published_at),INDEX(author_id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS teachers (id CHAR(36) PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT (''),content LONGTEXT NOT NULL DEFAULT (''),cover TEXT NOT NULL DEFAULT (''),status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'DRAFT',author_id CHAR(36),category_id CHAR(36),data JSON NOT NULL DEFAULT (JSON_OBJECT()),views INTEGER NOT NULL DEFAULT 0,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deleted_at DATETIME(3),INDEX(status,published_at),INDEX(author_id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pages (id CHAR(36) PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT (''),content LONGTEXT NOT NULL DEFAULT (''),cover TEXT NOT NULL DEFAULT (''),status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'DRAFT',author_id CHAR(36),category_id CHAR(36),data JSON NOT NULL DEFAULT (JSON_OBJECT()),views INTEGER NOT NULL DEFAULT 0,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),deleted_at DATETIME(3),INDEX(status,published_at),INDEX(author_id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS media (id CHAR(36) PRIMARY KEY,name VARCHAR(500) NOT NULL,alt TEXT NOT NULL DEFAULT (''),url TEXT NOT NULL,thumbnail TEXT NOT NULL,mime VARCHAR(100) NOT NULL,size INTEGER NOT NULL,storage_key VARCHAR(255) NOT NULL,author_id CHAR(36),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS album_images (album_id CHAR(36) NOT NULL,media_id CHAR(36) NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(album_id,media_id),FOREIGN KEY(album_id) REFERENCES albums(id) ON DELETE CASCADE,FOREIGN KEY(media_id) REFERENCES media(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS post_categories (post_id CHAR(36) NOT NULL,category_id CHAR(36) NOT NULL,PRIMARY KEY(post_id,category_id),FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS site_settings (`key` VARCHAR(191) PRIMARY KEY,value LONGTEXT NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS seo_settings (`key` VARCHAR(191) PRIMARY KEY,value LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS menus (id CHAR(36) PRIMARY KEY,name VARCHAR(191) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS menu_items (id CHAR(36) PRIMARY KEY,menu_id CHAR(36),parent_id CHAR(36),label VARCHAR(500) NOT NULL,url TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,visible BOOLEAN NOT NULL DEFAULT true,FOREIGN KEY(menu_id) REFERENCES menus(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES menu_items(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS contact_messages (id CHAR(36) PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(254) NOT NULL DEFAULT '',phone VARCHAR(50) NOT NULL DEFAULT '',subject VARCHAR(500) NOT NULL,message LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'UNREAD',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id CHAR(36),action TEXT NOT NULL,entity VARCHAR(191) NOT NULL,entity_id VARCHAR(191),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS rate_limits (`key` VARCHAR(191) PRIMARY KEY,count INTEGER NOT NULL DEFAULT 1,expires_at DATETIME(3) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO schema_migrations(version) VALUES(1) ON DUPLICATE KEY UPDATE version=version;

